<script setup>
import { ChevronRight, GraduationCap, Sparkles } from "lucide-vue-next";
import { useAppState } from "../composables/useAppState";
import { computed, ref } from "vue";

const {
  authError,
  loginRole,
  signIn,
  signUp,
  smuSchools,
  validPhone,
  phoneHint,
  toast,
} = useAppState();
const email = ref("");
const password = ref("");
const showPassword = ref(false);
document.title = "Log in · StudyBuds";

// Only students can sign up; admin accounts are created by an administrator.
const mode = ref("login");
const busy = ref(false);
const signup = ref({
  name: "",
  email: "",
  password: "",
  school: "",
  programme: "",
  yearOfStudy: "",
  contactNumber: "",
});
const showPhoneError = computed(
  () =>
    signup.value.contactNumber.trim() !== "" &&
    !validPhone(signup.value.contactNumber),
);

function switchMode(next) {
  if (busy.value) return;
  mode.value = next;
  showPassword.value = false;
  document.title =
    next === "signup" ? "Create account · StudyBuds" : "Log in · StudyBuds";
  authError.value = "";
  if (next === "signup") loginRole.value = "student";
}

// The first problem with the form, in the order the fields appear, or '' when it can be sent.
function signupProblem() {
  const form = signup.value;
  if (!form.name.trim()) return "Enter your name.";
  if (!form.email.trim()) return "Enter your email.";
  if (!/^\S+@\S+\.\S+$/.test(form.email.trim()))
    return "Enter a valid email address.";
  if (form.password.length < 8)
    return "Your password needs at least 8 characters.";
  if (!form.school) return "Choose your school.";
  if (!form.programme.trim()) return "Enter your programme.";
  if (!form.yearOfStudy) return "Choose your year of study.";
  if (!form.contactNumber.trim()) return "Enter your contact number.";
  if (!validPhone(form.contactNumber)) return `Contact number: ${phoneHint}.`;
  return "";
}

async function submitSignup() {
  const problem = signupProblem();
  if (problem) {
    authError.value = problem;
    toast(problem, "error");
    return;
  }
  const form = signup.value;
  busy.value = true;
  await signUp({
    name: form.name.trim(),
    email: form.email.trim(),
    password: form.password,
    school: form.school,
    programme: form.programme.trim(),
    yearOfStudy: Number(form.yearOfStudy),
    contactNumber: form.contactNumber.trim(),
  });
  busy.value = false;
}

async function submitLogin() {
  busy.value = true;
  await signIn(email.value, password.value);
  busy.value = false;
}
</script>

