            >
              {{ busy ? "Logging in…" : "Log in" }} <ChevronRight :size="16" />
            </button>
          </fieldset>
        </form>
        <button
          v-if="loginRole === 'student'"
          class="auth-switch"
          :disabled="busy"
          @click="switchMode('signup')"
        >
          New to StudyBuds? Create a student account
        </button>
      </template>
      <template v-else>
        <h1>Create your student account.</h1>
        <p class="auth-subtitle">
          All fields are required. You can add courses, goals and availability
          from your profile afterwards.
        </p>
        <form class="auth-form auth-signup" @submit.prevent="submitSignup">
          <fieldset class="plain-fieldset auth-form" :disabled="busy">
            <label class="field"
              ><span>Name</span
              ><input
