                <option v-for="school in smuSchools" :key="school">
                  {{ school }}
                </option>
              </select></label
            >
            <div class="auth-row">
              <label class="field"
                ><span>Programme</span
                ><input
                  v-model="signup.programme"
                  placeholder="Information Systems"
                  required
              /></label>
              <label class="field"
                ><span>Year of study</span
                ><select v-model="signup.yearOfStudy" required>
